  ('b8ad35aa-0f5c-43d7-9e9f-713f5977ef7a', 'barbell-bench-press', 'Barbell bench press', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Lie with eyes under the bar, feet planted and shoulder blades pulled back. Lower the bar to the lower chest with control, then press up and slightly back.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('539e0e72-75e4-417a-8f94-3c53e57077aa', 'incline-barbell-bench-press', 'Incline barbell bench press', 'chest', array['shoulders', 'triceps']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Set the bench to a low incline. Lower the bar to the upper chest with elbows slightly tucked, then press to lockout over the shoulders.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e7a98a05-045d-4502-bac6-a90bad0543e1', 'dumbbell-bench-press', 'Dumbbell bench press', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Start with the dumbbells over the chest. Lower them to the sides of the chest with forearms vertical, then press back up. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('717a474b-8a4f-4098-86bb-73ecad466f62', 'incline-dumbbell-press', 'Incline dumbbell press', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'On a low incline bench, lower the dumbbells beside the upper chest and press them up and slightly together. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('02516a94-577c-4d3c-acec-40c6110b874a', 'machine-chest-press', 'Machine chest press', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Set the seat so the handles line up with mid chest. Press forward without locking hard, then return slowly until you feel a stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('53e73b24-2365-401e-95b8-7ed7e5970bdb', 'smith-machine-bench-press', 'Smith machine bench press', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Position the bench so the bar touches the lower chest. Unhook, lower under control and press up along the fixed path.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f46fe50a-556d-4014-ace9-ac8599a9ef3d', 'cable-fly', 'Cable fly', 'chest', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Stand between the pulleys with a soft bend in the elbows. Bring the handles together in a wide arc in front of the chest, then open back to a stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e65cb0c2-74ea-48df-b323-624079528bb6', 'dumbbell-fly', 'Dumbbell fly', 'chest', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Lie on a flat bench with dumbbells over the chest and elbows slightly bent. Open the arms wide until you feel a stretch, then bring them back together.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('01347eae-f0ea-47c9-bc3f-af73a9fda7d8', 'pec-deck', 'Pec deck', 'chest', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Sit tall with the handles at chest height. Squeeze the arms together in front of you, pause briefly, then return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('13dfdf8b-99e3-4f1a-a303-bfa59d8103a4', 'push-up', 'Push-up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Hands slightly wider than shoulders and body in a straight line. Lower the chest to just above the floor, then push away.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('edbdbe30-008c-4ba2-b444-f7e1796b537d', 'dips', 'Dips', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Support yourself on the bars with a slight forward lean. Lower until the shoulders are just below the elbows, then press back up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e76e8540-57b8-44dd-ad96-70b78d434bb6', 'weighted-dips', 'Weighted dips', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'compound', 'weighted_bodyweight', 'total', 'Wear a belt or hold a dumbbell between the feet. Lower with a slight forward lean and press back up. Log only the added weight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('7c4da926-64bc-4a04-ad6c-7d5e815c3b97', 'deadlift', 'Deadlift', 'back', array['glutes', 'hamstrings', 'quads']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Bar over mid foot, hips back, back flat and arms straight. Push the floor away and stand tall, keeping the bar close to the legs.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f630f7e7-ebc7-4bd9-b4ab-cb85e1f1b350', 'pull-up', 'Pull-up', 'back', array['biceps']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Hang with an overhand grip slightly wider than shoulders. Pull the chest toward the bar by driving the elbows down, then lower to a full hang.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d36ea2fc-997e-4104-af46-b45d9da733cb', 'chin-up', 'Chin-up', 'back', array['biceps']::text[], 'bodyweight', 'compound', 'bodyweight_reps', 'total', 'Hang with an underhand, shoulder-width grip. Pull until the chin clears the bar, then lower under control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e034546a-2033-4e74-adf7-f80b8dd0c30d', 'weighted-pull-up', 'Weighted pull-up', 'back', array['biceps']::text[], 'bodyweight', 'compound', 'weighted_bodyweight', 'total', 'Add weight with a belt or vest and pull as for a pull-up. Log only the added weight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5729dda3-bc1c-4989-aa86-fa2c09d363b6', 'assisted-pull-up', 'Assisted pull-up', 'back', array['biceps']::text[], 'machine', 'compound', 'assisted_bodyweight', 'total', 'Kneel or stand on the assistance platform and pull as for a pull-up. Log the assistance weight; less assistance means more work.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e4248b43-1889-42e5-ad8e-435a497e9773', 'lat-pulldown', 'Lat pulldown', 'back', array['biceps']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Grip slightly wider than shoulders and lean back a little. Pull the bar to the upper chest by driving the elbows down, then let it rise to a full stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('18fd984f-b7e3-45d1-962b-9e1109e75b90', 'close-grip-lat-pulldown', 'Close-grip lat pulldown', 'back', array['biceps']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Use a narrow neutral handle. Pull it to the upper chest with elbows close to the body, then return to a full stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a409b613-53dd-49d6-a235-243e71ceb7ae', 'barbell-row', 'Barbell row', 'back', array['biceps', 'shoulders']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Hinge forward with a flat back and the bar hanging at arm length. Row it to the lower ribs, pause, then lower without letting the torso rise.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5120cffc-b5d4-4740-b177-abe2cd80c360', 'pendlay-row', 'Pendlay row', 'back', array['biceps', 'shoulders']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'With the torso near parallel to the floor, row the bar from a dead stop on the floor to the lower chest. Reset on the floor each rep.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c16d7528-bcc1-434c-8050-78094d8487aa', 'one-arm-dumbbell-row', 'One-arm dumbbell row', 'back', array['biceps']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Brace one hand on a bench. Row the dumbbell toward the hip, keeping the shoulder down, then lower to a full stretch. Log the dumbbell weight; reps are per side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5e8841e5-cbcb-4b39-986a-ad1a51265fb2', 'chest-supported-row', 'Chest-supported row', 'back', array['biceps', 'shoulders']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Lie face down on an incline bench. Row both dumbbells up and back, squeeze the shoulder blades, then lower. Log the weight of one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('da9d0bd1-8ceb-408d-a386-4d4a0d1ecf87', 'seated-cable-row', 'Seated cable row', 'back', array['biceps']::text[], 'cable', 'compound', 'weight_reps', 'total', 'Sit tall with a slight knee bend. Pull the handle to the stomach while keeping the chest up, then reach forward to a stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d5f1040b-7941-49ba-b1b7-ced085729fb6', 'machine-row', 'Machine row', 'back', array['biceps']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Set the chest pad so you can reach the handles at full stretch. Pull the elbows back, pause, and return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('b4439f69-0942-405a-984f-0ee3e93eeff1', 't-bar-row', 'T-bar row', 'back', array['biceps', 'shoulders']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Straddle the bar with a flat back and hinge forward. Row the handle to the chest, then lower to a full stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('02812403-6d9c-4a2c-9eb5-ff4531016b74', 'straight-arm-pulldown', 'Straight-arm pulldown', 'back', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Face a high pulley with arms nearly straight. Sweep the bar down to the thighs using the lats, then let it rise slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('44db6104-eee0-4d0f-ab94-ac6c0196bbf0', 'back-extension', 'Back extension', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Set the pad at the hips. Lower the torso with a neutral spine, then lift back up until the body is straight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
