  ('d57fadd1-2600-44e1-8a20-8d60ed51bfa5', 'overhead-press', 'Overhead press', 'shoulders', array['triceps']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Start with the bar on the front of the shoulders and glutes tight. Press it straight up, moving the head back then through, and lock out overhead.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
