  ('89daf7c1-de83-4c1d-bea3-c76d8d5e6b77', 'machine-shoulder-press', 'Machine shoulder press', 'shoulders', array['triceps']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Set the seat so the handles start at shoulder height. Press up without shrugging, then lower under control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
