  ('f1f29c78-36bb-4861-b646-58a1a176ffce', 'dumbbell-lateral-raise', 'Dumbbell lateral raise', 'shoulders', array[]::text[], 'dumbbell', 'isolation', 'weight_reps', 'per_hand', 'Stand with a slight forward lean. Raise the dumbbells out to the sides to shoulder height, leading with the elbows, then lower slowly. Log one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
