  ('1f28c15b-c3b8-4855-95d5-9ce5a51e33eb', 'machine-lateral-raise', 'Machine lateral raise', 'shoulders', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Line the shoulders up with the machine pivot. Raise the pads out to the sides to shoulder height, then lower under control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
