  ('6838715f-30ae-4655-a576-4dfb81ef6323', 'reverse-pec-deck', 'Reverse pec deck', 'shoulders', array['back']::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Face the pad with the handles at shoulder height. Sweep the arms back and out, pause, then return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
