  ('75287645-dac6-400a-b620-ee51a1539321', 'hack-squat', 'Hack squat', 'quads', array['glutes']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Shoulders under the pads and feet mid platform. Lower until the thighs are at least parallel, then press up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1786e67c-2f33-4ea9-8591-7187eda38351', 'leg-press', 'Leg press', 'quads', array['glutes']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Feet shoulder width on the platform. Lower until the knees are well bent without the lower back lifting off the pad, then press.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('d5f437ea-90b3-4b15-946f-e24e9db89b35', 'goblet-squat', 'Goblet squat', 'quads', array['glutes']::text[], 'dumbbell', 'compound', 'weight_reps', 'total', 'Hold one dumbbell at the chest. Squat down with the elbows inside the knees, then stand up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5a513142-05ec-44ab-a2c3-100b79fa2310', 'bulgarian-split-squat', 'Bulgarian split squat', 'quads', array['glutes']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Rear foot on a bench and dumbbells at your sides. Lower the back knee toward the floor, then drive up through the front foot. Log one dumbbell; reps are per leg.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('4482c8af-8102-4685-94b4-87c4d190670d', 'walking-lunge', 'Walking lunge', 'quads', array['glutes']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Step forward and lower the back knee toward the floor, then step through into the next lunge. Log one dumbbell and total steps as reps.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ed7fe0bf-bb9d-4ef0-934e-1b58bdfd0faf', 'leg-extension', 'Leg extension', 'quads', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Line the knees up with the machine pivot. Straighten the legs, pause, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f96eb825-e129-4543-a1d7-5a5ecdff833b', 'step-up', 'Dumbbell step-up', 'quads', array['glutes']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Step onto a box with the whole foot and drive up to stand on it, then step down with control. Log one dumbbell; reps are per leg.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('50825b5e-192c-4c07-b48c-1ed5010dc7af', 'romanian-deadlift', 'Romanian deadlift', 'hamstrings', array['glutes', 'back']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Stand with the bar at the hips and knees soft. Push the hips back, sliding the bar down the thighs until you feel a strong stretch, then stand up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('765a0aa6-362a-4b4e-b92c-0998093693a4', 'dumbbell-romanian-deadlift', 'Dumbbell Romanian deadlift', 'hamstrings', array['glutes', 'back']::text[], 'dumbbell', 'compound', 'weight_reps', 'per_hand', 'Hinge at the hips with the dumbbells close to the legs and a flat back, then stand tall. Log one dumbbell.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ca05cef6-229c-47e0-9df0-adcd319a73c6', 'stiff-leg-deadlift', 'Stiff-leg deadlift', 'hamstrings', array['glutes', 'back']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Start from the floor with knees only slightly bent. Lift by extending the hips, keeping the back flat.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('9a5aba95-8693-472b-b1a0-4d1fa9000b25', 'lying-leg-curl', 'Lying leg curl', 'hamstrings', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Lie face down with the pad above the heels. Curl the heels toward the glutes, then lower slowly to straight.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ff649cd7-65e8-4d52-b36f-a662a586b7b5', 'seated-leg-curl', 'Seated leg curl', 'hamstrings', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Sit with the thigh pad snug and the lower pad above the heels. Curl down and back, then return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('b336366e-fd28-4515-8fef-243eddd57f8b', 'nordic-curl', 'Nordic curl', 'hamstrings', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Kneel with the ankles anchored. Lower the body forward as slowly as you can, catch yourself, and push back up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('670e46a9-70e6-4d79-92c0-4d531523c7a5', 'good-morning', 'Good morning', 'hamstrings', array['glutes', 'back']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Bar on the upper back and knees soft. Hinge forward with a flat back until you feel the hamstrings stretch, then stand up.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('fd120737-3218-40a2-be3a-df52f510bfe2', 'hip-thrust', 'Hip thrust', 'glutes', array['hamstrings']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Upper back on a bench and bar over the hips. Drive the hips up until the body is flat from shoulders to knees, pause, then lower.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a152eb68-aedc-408c-8692-ff5ebda0ef3a', 'machine-hip-thrust', 'Machine hip thrust', 'glutes', array['hamstrings']::text[], 'machine', 'compound', 'weight_reps', 'total', 'Set the pad across the hips. Drive up to full hip extension, pause, then lower under control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1a21618f-5036-4cd8-8792-472395db0fd0', 'glute-bridge', 'Glute bridge', 'glutes', array['hamstrings']::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Lie on your back with knees bent. Push through the heels to lift the hips, squeeze, then lower.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('7ab92357-6a60-43dd-bd1c-84fbb53a732c', 'cable-kickback', 'Cable glute kickback', 'glutes', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Attach an ankle strap to a low pulley. Kick the leg back and slightly up without arching the lower back. Reps are per leg.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('1aaa6709-e158-4cc9-8aa4-da3af11b035a', 'hip-abduction', 'Hip abduction machine', 'glutes', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Sit tall and push the pads apart, pause, then return slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ed5f44d3-7fb3-4ae0-8f53-cb552d8b47bd', 'sumo-deadlift', 'Sumo deadlift', 'glutes', array['quads', 'hamstrings', 'back']::text[], 'barbell', 'compound', 'weight_reps', 'total', 'Wide stance with toes turned out and hands inside the knees. Push the knees out and stand up with the bar close.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a1f9c37d-adb6-4731-913a-1b0bf580436a', 'standing-calf-raise', 'Standing calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Balls of the feet on the edge of the platform. Lower the heels to a full stretch, pause, then rise as high as you can.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('e95364a1-ff9c-4ab9-97e6-e3163dd3579c', 'seated-calf-raise', 'Seated calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'Pad on the lower thighs and balls of the feet on the platform. Lower to a deep stretch, then rise fully.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('05a80d3b-1cf7-4ba8-a896-1407edb2df15', 'leg-press-calf-raise', 'Leg press calf raise', 'calves', array[]::text[], 'machine', 'isolation', 'weight_reps', 'total', 'With legs straight, place the balls of the feet on the low edge of the platform. Push through the toes, then lower to a stretch.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('5a460329-698f-4448-8ea3-06b4c1740b1a', 'single-leg-calf-raise', 'Single-leg calf raise', 'calves', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Stand on one foot on a step. Lower the heel below the step, then rise onto the toes. Reps are per leg.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('91182ef9-67de-4e89-93d5-552a4dc937ee', 'hanging-leg-raise', 'Hanging leg raise', 'abs', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Hang from a bar. Raise the legs by curling the pelvis up, avoiding a swing, then lower slowly.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('6a13b7da-581c-48ee-9f2c-4dda158a7fcd', 'cable-crunch', 'Cable crunch', 'abs', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Kneel facing a high pulley holding the rope by your head. Curl the ribs toward the hips, then return.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ee3ba745-f24b-433f-a1bb-18970db08356', 'crunch', 'Crunch', 'abs', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Lie on your back with knees bent. Curl the shoulders off the floor by bringing the ribs toward the pelvis, then lower.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('eace603f-f4d0-4855-8354-cac4d1e2e73a', 'ab-wheel-rollout', 'Ab wheel rollout', 'abs', array[]::text[], 'other', 'isolation', 'bodyweight_reps', 'total', 'Kneel holding the wheel. Roll forward as far as you can without the lower back sagging, then pull back.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('c43f8530-b62f-45a9-9bd4-386179859b53', 'decline-sit-up', 'Decline sit-up', 'abs', array[]::text[], 'bodyweight', 'isolation', 'bodyweight_reps', 'total', 'Hook the feet on a decline bench. Curl up to sitting, then lower under control.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('452e5fb1-ab79-489e-ab24-b6e805ca5f18', 'plank', 'Plank', 'abs', array[]::text[], 'bodyweight', 'isolation', 'duration', 'total', 'Forearms under the shoulders and body in a straight line. Brace and hold without letting the hips sag. Log the time held.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('a9400a5f-a667-4cec-82a9-fee7b1e68bc3', 'side-plank', 'Side plank', 'abs', array[]::text[], 'bodyweight', 'isolation', 'duration', 'total', 'Support yourself on one forearm with the body straight from head to feet. Hold, then switch sides. Log the time per side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('3be01731-94ed-41b8-a210-90edb9b1cb2e', 'pallof-press', 'Pallof press', 'abs', array[]::text[], 'cable', 'isolation', 'weight_reps', 'total', 'Stand side-on to a pulley at chest height. Press the handle straight out and resist the pull to rotate, then bring it back. Reps are per side.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('8f779720-339e-481d-ad03-66d36d9eeb8b', 'farmers-carry', 'Farmer''s carry', 'back', array['abs']::text[], 'dumbbell', 'compound', 'distance', 'total', 'Hold heavy dumbbells at your sides, stand tall and walk with short steps. Log the distance covered.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('f69431f4-00f8-40a9-939c-0bb90db39f6c', 'kettlebell-swing', 'Kettlebell swing', 'glutes', array['hamstrings', 'back']::text[], 'kettlebell', 'compound', 'weight_reps', 'total', 'Hike the bell back between the legs, then snap the hips forward to float it to chest height. Let it fall back into the next rep.', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
